import java.io.*;

public class Main {
    static boolean isUpper(char c) { return c >= 'A' && c <= 'Z'; }
    static boolean isDigit(char c) { return c >= '0' && c <= '9'; }

    static boolean oldPattern(String p) {
        if (p.length() != 8) return false;
        for (int i = 0; i < 3; i++) if (!isUpper(p.charAt(i))) return false;
        if (p.charAt(3) != '-') return false;
        for (int i = 4; i < 8; i++) if (!isDigit(p.charAt(i))) return false;
        return true;
    }

    static boolean mercosulPattern(String p) {
        if (p.length() != 7) return false;
        for (int i = 0; i < 3; i++) if (!isUpper(p.charAt(i))) return false;
        if (!isDigit(p.charAt(3))) return false;
        if (!isUpper(p.charAt(4))) return false;
        for (int i = 5; i < 7; i++) if (!isDigit(p.charAt(i))) return false;
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String placa = br.readLine().trim();
        int resultado = 0;
        if (oldPattern(placa)) resultado = 1;
        else if (mercosulPattern(placa)) resultado = 2;
        System.out.println(resultado);
    }
}
